// GPL-3.0-only. Zero-Model algebra and analytic integration of the production SOT RHS.
#define FIM_USER_LIBRARY 1
#include "user_native.cpp"
#undef FIM_USER_LIBRARY
#include "current_sot.hpp"
#include <random>
int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("NEW_OUTPUT");std::filesystem::path out=argv[1];if(std::filesystem::exists(out))throw std::runtime_error("output exists");std::filesystem::create_directory(out);UserConfig u;u.c.Ms={3e5,6e5};u.gamma={GAMMA_SD,1.8e5};u.c.h={4e-9,4e-9,3e-9};u.alpha={.01,.07};CurrentSOT d;d.d={0,0,1};d.J={1e11,0,0};d.xi={.1,.1};d.r={.2,-.3};std::mt19937 rng(20261016);std::uniform_real_distribution<double>rand(-1,1);double error=0;std::ofstream cases(out/"rhs_cases.csv");cases<<std::setprecision(17)<<"case,sub,mx,my,mz,Hx,Hy,Hz,Ms,gamma,alpha,xi,r,Jx,Jy,dx,dy,dz,fx,fy,fz,drive_x,drive_y,drive_z\n";unsigned long rhs=0;
 for(int k=0;k<128;k++){CurrentSOT c=d;if(k%8==0)c.J={};if(k%8==1)c.xi={};if(k%8==2)c.xi[1]=0;if(k%8==3)c.xi[0]=0;if(k%8==4)c.J=d.J*(-1);if(k%8==5)c.xi[0]=-.1;if(k%8==6)c.d={1,0,0};if(k%8==7)c.d={0,.6,.8};for(int i=0;i<2;i++){V m{rand(rng),rand(rng),rand(rng)};m=m*(1/norm(m));if(k%3==0)m=m*1.0001;V H{123,-234,345};auto actual=sot_rhs(m,H,i,u,c);auto q=sot_cross(c.d,c.J);double a=c.xi[i]*SOT_MUB_E/(u.c.Ms[i]*u.c.h[2])/(1+u.alpha[i]*u.alpha[i]);V explicit_drive=(sot_cross(m,sot_cross(m,q))*(1+u.alpha[i]*c.r[i])+sot_cross(m,q)*(c.r[i]-u.alpha[i]*dot(m,m)))*a;V expected=gilbert(m,H,u.gamma[i]/GAMMA_SD,u.alpha[i])+explicit_drive;error=std::max(error,norm(actual-expected)/1e9);rhs++;auto only=sot_only(m,i,u,c);cases<<k<<','<<i<<','<<m.x<<','<<m.y<<','<<m.z<<','<<H.x<<','<<H.y<<','<<H.z<<','<<u.c.Ms[i]<<','<<u.gamma[i]<<','<<u.alpha[i]<<','<<c.xi[i]<<','<<c.r[i]<<','<<c.J.x<<','<<c.J.y<<','<<c.d.x<<','<<c.d.y<<','<<c.d.z<<','<<actual.x<<','<<actual.y<<','<<actual.z<<','<<only.x<<','<<only.y<<','<<only.z<<'\n';}}
 if(error>1e-12)throw std::runtime_error("algebra1e-12");std::ofstream macro(out/"macro.csv");macro<<std::setprecision(17)<<"kind,steps,sub,error,raw,angle_expected\n";for(int kind=0;kind<2;kind++)for(int count:{64,128,256}){double T=.2e-9,h=T/count;u.alpha=kind?std::array<double,2>{.2,.25}:std::array<double,2>{0,0};d.r=kind?std::array<double,2>{-5,-4}:std::array<double,2>{0,0};for(int i=0;i<2;i++)d.xi[i]=(i?0.5e9:1e9)*u.c.Ms[i]*u.c.h[2]/(SOT_MUB_E*1e11);for(int i=0;i<2;i++){V m{std::sqrt(.96),.2,0},initial=m;double raw=0,c=i?.5e9:1e9;for(int k=0;k<count;k++){auto f=[&](V v){rhs++;return sot_rhs(v,{},i,u,d);};V k1=f(m),k2=f(m+k1*(h/2)),k3=f(m+k2*(h/2)),k4=f(m+k3*h);m+=(k1+k2*2+k3*2+k4)*(h/6);double n=std::hypot(m.x,m.y,m.z);raw=std::max(raw,std::abs(n-1));m={m.x/n,m.y/n,m.z/n};}double angle=kind?c/u.alpha[i]*T:0;V expected;if(kind){V p{0,1,0};expected=initial*std::cos(angle)+sot_cross(p,initial)*std::sin(angle)+p*(dot(p,initial)*(1-std::cos(angle)));}else{double v=std::tanh(std::atanh(.2)-c*T);expected={std::sqrt(1-v*v),v,0};}double e=norm(m-expected);macro<<kind<<','<<count<<','<<i<<','<<e<<','<<raw<<','<<angle<<'\n';if(e>1e-8||raw>1e-8)throw std::runtime_error("macro gate");}}
 std::ofstream result(out/"result.json");result<<std::setprecision(17)<<"{\"passed\":true,\"Models\":0,\"FiM_fields\":0,\"scalar_vector_RHS\":"<<rhs<<",\"algebra_error\":"<<error<<"}\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 2;}}
